   100  int IFileReaderDevice::getNextPackets(RawPacketVector& packetVec, int numOfPacketsToRead)
   101  {
   102          int numOfPacketsRead = 0;
   103
   104          for (; numOfPacketsToRead < 0 || numOfPacketsRead < numOfPacketsToRead; numOfPacketsRead++)
   105          {
   106                  RawPacket* newPacket = new RawPacket();
   107                  bool packetRead = getNextPacket(*newPacket);
   108                  if (packetRead)
   109                  {
   110                          packetVec.pushBack(newPacket);
   111                  }
   112                  else
   113                  {
   114                          delete newPacket;
   115                          break;
   116                  }
   117          }
   118
   119          return numOfPacketsRead;
   120  }
