   241  {
   242          size_t hdrLen = getHeaderLen();
   243          if (m_DataLen <= hdrLen || hdrLen == 0)
   244                  return;
   245
   246          iphdr* ipHdr = getIPv4Header();
   247
   248          ProtocolType greVer = UnknownProtocol;
   249          ProtocolType igmpVer = UnknownProtocol;
   250          bool igmpQuery = false;
   251
   252          uint8_t ipVersion = 0;
   253
   254          uint8_t* payload = m_Data + hdrLen;
   255          size_t payloadLen = m_DataLen - hdrLen;
   256
   257          // If it's a fragment don't parse upper layers, unless if it's the first fragment
   258          // TODO: assuming first fragment contains at least L4 header, what if it's not true?
   259          if (isFragment())
   260          {
   261                  m_NextLayer = new PayloadLayer(payload, payloadLen, this, m_Packet);
   262                  return;
   263          }
   264
   265          switch (ipHdr->protocol)
   266          {
   267          case PACKETPP_IPPROTO_UDP:
   268                  if (payloadLen >= sizeof(udphdr))
   269                          m_NextLayer = new UdpLayer(payload, payloadLen, this, m_Packet);
   270                  break;
   271          case PACKETPP_IPPROTO_TCP:
   272                  m_NextLayer = TcpLayer::isDataValid(payload, payloadLen)
   273                          ? static_cast<Layer*>(new TcpLayer(payload, payloadLen, this, m_Packet))
   274                          : static_cast<Layer*>(new PayloadLayer(payload, payloadLen, this, m_Packet));
   275                  break;
   276          case PACKETPP_IPPROTO_ICMP:
   277                  m_NextLayer = IcmpLayer::isDataValid(payload, payloadLen)
   278                          ? static_cast<Layer*>(new IcmpLayer(payload, payloadLen, this, m_Packet))
   279                          : static_cast<Layer*>(new PayloadLayer(payload, payloadLen, this, m_Packet));
   280                  break;
   281          case PACKETPP_IPPROTO_IPIP:
   282                  ipVersion = *payload >> 4;
   283                  if (ipVersion == 4 && IPv4Layer::isDataValid(payload, payloadLen))
   284                          m_NextLayer = new IPv4Layer(payload, payloadLen, this, m_Packet);
   285                  else if (ipVersion == 6 && IPv6Layer::isDataValid(payload, payloadLen))
   286                          m_NextLayer = new IPv6Layer(payload, payloadLen, this, m_Packet);
   287                  else
   288                          m_NextLayer = new PayloadLayer(payload, payloadLen, this, m_Packet);
   289                  break;
   290          case PACKETPP_IPPROTO_GRE:
   291                  greVer = GreLayer::getGREVersion(payload, payloadLen);
   292                  if (greVer == GREv0)
   293                          m_NextLayer = new GREv0Layer(payload, payloadLen, this, m_Packet);
   294                  else if (greVer == GREv1)
   295                          m_NextLayer = new GREv1Layer(payload, payloadLen, this, m_Packet);
   296                  else
   297                          m_NextLayer = new PayloadLayer(payload, payloadLen, this, m_Packet);
   298                  break;
   299          case PACKETPP_IPPROTO_IGMP:
   300                  igmpVer = IgmpLayer::getIGMPVerFromData(
   301                          payload, std::min<size_t>(payloadLen, be16toh(getIPv4Header()->totalLength) - hdrLen), igmpQuery);
   302                  if (igmpVer == IGMPv1)
   303                          m_NextLayer = new IgmpV1Layer(payload, payloadLen, this, m_Packet);
   304                  else if (igmpVer == IGMPv2)
   305                          m_NextLayer = new IgmpV2Layer(payload, payloadLen, this, m_Packet);
   306                  else if (igmpVer == IGMPv3)
   307                  {
   308                          if (igmpQuery)
   309                                  m_NextLayer = new IgmpV3QueryLayer(payload, payloadLen, this, m_Packet);
   310                          else
   311                                  m_NextLayer = new IgmpV3ReportLayer(payload, payloadLen, this, m_Packet);
   312                  }
   313                  else
   314                          m_NextLayer = new PayloadLayer(payload, payloadLen, this, m_Packet);
   315                  break;
   316          case PACKETPP_IPPROTO_AH:
   317                  m_NextLayer = AuthenticationHeaderLayer::isDataValid(payload, payloadLen)
   318                          ? static_cast<Layer*>(new AuthenticationHeaderLayer(payload, payloadLen, this, m_Packet))
   319                          : static_cast<Layer*>(new PayloadLayer(payload, payloadLen, this, m_Packet));
   320                  break;
