   542  bool IPv4Layer::removeOption(IPv4OptionTypes option)
   543  {
   544          IPv4Option opt = getOption(option);
   545          if (opt.isNull())
   546          {
   547                  return false;
   548          }
   549
   550          // calculate total option size
   551          IPv4Option curOpt = getFirstOption();
   552          size_t totalOptSize = 0;
   553          while (!curOpt.isNull())
   554          {
   555                  totalOptSize += curOpt.getTotalSize();
   556                  curOpt = getNextOption(curOpt);
   557          }
   558          totalOptSize -= opt.getTotalSize();
   559
   560
   561          int offset = opt.getRecordBasePtr() - m_Data;
   562
   563          size_t sizeToShorten = opt.getTotalSize();
   564          if (!shortenLayer(offset, sizeToShorten))
   565          {
   566                  PCPP_LOG_ERROR("Failed to remove IPv4 option: cannot shorten layer");
   567                  return false;
   568          }
   569
   570          // setting this m_TempHeaderExtension because adjustOptionsTrailer() may extend or shorten the layer and the extend or shorten methods need to know the accurate
   571          // current size of the header. m_TempHeaderExtension will be added to the length extracted from getIPv4Header()->internetHeaderLength as the temp new size
   572          m_TempHeaderExtension = 0 - sizeToShorten;
   573          adjustOptionsTrailer(totalOptSize);
   574          // the adjustOptionsTrailer() adds or removed the trailing bytes and sets getIPv4Header()->internetHeaderLength to the correct size, so the m_TempHeaderExtension
   575          // isn't needed anymore
   576          m_TempHeaderExtension = 0;
   577
   578          m_OptionReader.changeTLVRecordCount(-1);
   579
   580          return true;
   581  }
